/* The base Notebook rotates summary spans; only our plus icon should rotate. */
[data-template-theme="notebook-white"] .purple-note[open] > summary span,
[data-template-theme="notebook-white"] .purple-timeline-entry[open] > summary span {
  transform: none;
}
